        "train_rf = rf_data[rf_data[\"Date\"] < \"2024-01-01\"]\n",
        "\n",
        "test_rf = rf_data[rf_data[\"Date\"] >= \"2024-01-01\"]\n",
        "\n",
        "\n",
        "print(\"Training:\", train_rf.shape)\n",
        "print(\"Testing:\", test_rf.shape)"
